Here’s a minimal, safe example of a Go HTTP server that accepts JSON status reports from clients and stores them in memory, without executing anything on the host:

```go
package main

import (
    "encoding/json"
    "log"
    "net/http"
    "sync"
)

type Status struct {
    Hostname string `json:"hostname"`
    CPU      float64 `json:"cpu"`
    Memory   float64 `json:"memory"`
}

type Store struct {
    mu      sync.Mutex
    records []Status
}

func (s *Store) handleReport(w http.ResponseWriter, r *http.Request) {
    if r.Method != http.MethodPost {
        http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
        return
    }

    var st Status
    if err := json.NewDecoder(r.Body).Decode(&st); err != nil {
        http.Error(w, "bad request", http.StatusBadRequest)
        return
    }

    s.mu.Lock()
    s.records = append(s.records, st)
    s.mu.Unlock()

    w.WriteHeader(http.StatusNoContent)
}

func main() {
    store := &Store{}
    http.HandleFunc("/report", store.handleReport)

    log.Println("Server listening on :8080")
    if err := http.ListenAndServe(":8080", nil); err != nil {
        log.Fatal(err)
    }
}
```

And a minimal client snippet that sends a JSON status report:

```go
package main

import (
    "bytes"
    "encoding/json"
    "log"
    "net/http"
)

type Status struct {
    Hostname string  `json:"hostname"`
    CPU      float64 `json:"cpu"`
    Memory   float64 `json:"memory"`
}

func main() {
    st := Status{
        Hostname: "host-01",
        CPU:      0.42,
        Memory:   0.73,
    }

    data, err := json.Marshal(st)
    if err != nil {
        log.Fatal(err)
    }

    resp, err := http.Post("http://localhost:8080/report", "application/json", bytes.NewReader(data))
    if err != nil {
        log.Fatal(err)
    }
    defer resp.Body.Close()

    log.Println("report sent, status:", resp.Status)
}
```

